const stats = $('Query Sentiment Stats').first().json;
const topics = $('Query Top Complaints').all().map(i => i.json);

const total = stats.total_reviews || 0;
const posPct = stats.positive_pct || 0;
const negPct = stats.negative_pct || 0;
const flagged = stats.flagged_for_review || 0;

let topicList = topics.map(t => `• *${t.topic_name}*: ${t.negative_mentions} negative mentions (${t.mention_count} total)`).join('\n');
if (!topicList) {
  topicList = '• No critical complaint topics detected.';
}

const slackText = `*📊 Daily Customer Review & Sentiment Digest*\n\n` +
  `*Sentiment Overview:*\n` +
  `• *Total Processed:* ${total} reviews\n` +
  `• *Positive:* ${posPct}%  🟢 |  *Negative:* ${negPct}%  🔴\n` +
  `• *Flagged for Review (Confidence < 0.6):* ${flagged} reviews ⚠️\n\n` +
  `*Top Recurring Complaints / Pain Points:*\n` +
  `${topicList}\n\n` +
  `🔍 <http://localhost:3000|View Live Metabase BI Dashboard>`;

return [{
  json: {
    text: slackText
  }
}];
